namespace Ordering;

/// <summary>Handles product returns, the refunds they trigger and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnProcessor _returnProcessor;
    private readonly ReturnabilityPolicy _returnabilityPolicy;
    private readonly RefundCalculator _refundCalculator;
    private readonly RefundJournal _refundJournal;
    private readonly ReturnInventory _returnInventory;

    public ReturnsHandler()
    {
        var processedReturns = new ProcessedReturnRegistry();
        _returnInventory = new ReturnInventory();
        _refundJournal = new RefundJournal();
        _returnProcessor = new ReturnProcessor(processedReturns, _returnInventory);
        _returnabilityPolicy = new ReturnabilityPolicy(processedReturns);
        _refundCalculator = new RefundCalculator(_refundJournal);
    }

    public string ProcessReturn(Order order, Customer customer) =>
        _returnProcessor.Process(order, customer);

    public bool IsReturnable(Order order) =>
        _returnabilityPolicy.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _refundCalculator.Compute(order);

    public void LogRefund(Order order, decimal amount) =>
        _refundJournal.Log(order, amount);

    public int Restock(Order order) =>
        _returnInventory.Restock(order);
}

internal sealed class ProcessedReturnRegistry
{
    private readonly HashSet<string> _references = new(StringComparer.Ordinal);

    public bool Contains(string reference) => _references.Contains(reference);

    public void Add(string reference) => _references.Add(reference);
}

internal sealed class ReturnProcessor
{
    private readonly ProcessedReturnRegistry _processedReturns;
    private readonly ReturnInventory _inventory;

    public ReturnProcessor(
        ProcessedReturnRegistry processedReturns,
        ReturnInventory inventory)
    {
        _processedReturns = processedReturns;
        _inventory = inventory;
    }

    public string Process(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_processedReturns.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        var inventoryResult = _inventory.RecordReturnedLines(order);
        if (inventoryResult == ReturnedLinesResult.QuantityTooHigh)
            return "quantity too high";
        if (!_inventory.HasEntries)
            return "no returnable lines";

        _processedReturns.Add(order.Reference);
        return "accepted";
    }
}

internal sealed class ReturnabilityPolicy
{
    private readonly ProcessedReturnRegistry _processedReturns;

    public ReturnabilityPolicy(ProcessedReturnRegistry processedReturns)
    {
        _processedReturns = processedReturns;
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_processedReturns.Contains(order.Reference))
            return false;

        int valid = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (string.IsNullOrEmpty(line.Sku))
                continue;
            if (line.Quantity > 100)
                continue;
            if (line.Quantity >= 1 && line.Quantity <= 100)
                valid++;
        }

        return valid > 0;
    }
}

internal sealed class RefundCalculator
{
    private const decimal UnitRefund = 5m;
    private readonly RefundJournal _refundJournal;

    public RefundCalculator(RefundJournal refundJournal)
    {
        _refundJournal = refundJournal;
    }

    public decimal Compute(Order order)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 50)
                refund += line.Quantity * UnitRefund * 0.9m;
            else if (line.Quantity > 10)
                refund += line.Quantity * UnitRefund * 0.95m;
            else if (line.Quantity > 1)
                refund += line.Quantity * UnitRefund;
            else
                refund += UnitRefund;
        }

        if (_refundJournal.Count > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;
        return refund < 0m ? 0m : refund;
    }
}

internal sealed class RefundJournal
{
    private readonly List<string> _entries = new();

    public int Count => _entries.Count;

    public void Log(Order order, decimal amount)
    {
        if (amount <= 0m)
            return;
        if (string.IsNullOrEmpty(order.Reference))
            return;
        if (_entries.Count == 0 || amount > 100m)
            _entries.Add($"{order.Reference}:{amount}");
        else if (amount > 50m)
            _entries.Add($"{order.Reference}:large:{amount}");
        else if (amount > 10m)
            _entries.Add($"{order.Reference}:mid:{amount}");
        else
            _entries.Add($"{order.Reference}:small:{amount}");
        if (_entries.Count > 500 && amount > 1000m)
            _entries.Add($"{order.Reference}:flag");
    }
}

internal enum ReturnedLinesResult
{
    Recorded,
    QuantityTooHigh
}

internal sealed class ReturnInventory
{
    private readonly Dictionary<string, int> _restockBySku = new(StringComparer.Ordinal);

    public bool HasEntries => _restockBySku.Count != 0;

    public ReturnedLinesResult RecordReturnedLines(Order order)
    {
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return ReturnedLinesResult.QuantityTooHigh;
            _restockBySku[line.Sku] = _restockBySku.TryGetValue(line.Sku, out var count)
                ? count + line.Quantity
                : line.Quantity;
        }

        return ReturnedLinesResult.Recorded;
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            var sku = line.Sku;
            if (string.IsNullOrEmpty(sku))
                continue;
            if (line.Quantity > 100)
                continue;
            if (_restockBySku.TryGetValue(sku, out var pending) && pending > 0)
            {
                moved += pending;
                _restockBySku[sku] = 0;
            }
            else if (line.Quantity > 50)
            {
                _restockBySku[sku] = line.Quantity / 2;
            }
            else if (line.Quantity > 0)
            {
                _restockBySku[sku] = line.Quantity;
            }
            if (moved > 100000)
                break;
        }

        return moved;
    }
}
